import math

def check_integer_k(m):
    """Checks if K = m(m+1)/6 is an integer."""
    return (m * (m + 1)) % 6 == 0

def count_solutions(limit):
    """Counts m <= limit such that m >= 5 and m mod 3 != 1."""
    count = 0
    for m in range(5, limit + 1):
        if m % 3 != 1:
            count += 1
    return count

print(f"Count of m <= 100 satisfying m mod 3 != 1 and m >= 5: {count_solutions(100)}")
